#!/usr/bin/env bash
# Fetch the annotated datasets used by the experiments and verify them against
# datasets/MANIFEST.sha256 (the checksums of the exact files behind every
# number in the paper).
#
# Provenance. Sequence structure comes from the public SPMF datasets; item
# quantities and unit profits were generated by src/main/java/SPMF_Converter.java
# (seed 42). Three datasets (BIBLE, BMS1, C8T1S5I8N5K) are value-identical to
# release v1.1-seed42-lognormal of https://github.com/tran-minh-thai/huspm-datasets
# (only the comment line of the _eui file differs); FIFA, KOSARAK, LEVIATHAN and
# SIGN were produced by an earlier batch conversion whose generator was shared
# across the batch and therefore cannot be regenerated from the raw SPMF files
# with a per-file seed. All seven are distributed verbatim as a release asset of
# this repository and pinned by the manifest.
#
# Usage:
#   ./scripts/fetch_datasets.sh                # download + verify into datasets/
#   ./scripts/fetch_datasets.sh --verify-only  # only check files already present
#
# Override the source with DATASETS_URL=<url of the .tar.gz>.
set -euo pipefail

cd "$(dirname "$0")/.."
TAG="${DATASETS_TAG:-datasets-v1-hausp-ub}"
REPO="${DATASETS_REPO:-tran-minh-thai/incremental-hausp-mining}"
URL="${DATASETS_URL:-https://github.com/$REPO/releases/download/$TAG/hausp-ub-datasets-$TAG.tar.gz}"

if [ "${1:-}" != "--verify-only" ]; then
    echo "[fetch] downloading $URL"
    tmp="$(mktemp -t hausp-datasets.XXXXXX.tar.gz)"
    curl -fL --retry 3 -o "$tmp" "$URL"
    echo "[fetch] extracting into datasets/"
    tar xzf "$tmp" -C datasets
    rm -f "$tmp"
fi

echo "[fetch] verifying against datasets/MANIFEST.sha256"
cd datasets
if command -v shasum >/dev/null 2>&1; then
    shasum -a 256 -c MANIFEST.sha256
else
    sha256sum -c MANIFEST.sha256
fi
echo "[fetch] all files match the manifest"
